import{_ as a,o as n,c as s,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/plugins.md","filePath":"es-ES/user-guide/settings/plugins.md","lastUpdated":1785993908000}'),l={name:"es-ES/user-guide/settings/plugins.md"};function r(i,e,t,u,d,p){return n(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p>Lista cada plugin instalado, con la versión del SDK de Plugins cargada actualmente mostrada como una insignia en la cabecera de la página — haz clic en ella para abrir el <a href="./../../dev-guide/">Manual de Desarrollador</a>, que es justamente para lo que sirve ese número de versión.</p><p>La página se divide en dos paneles: los plugins instalados a la izquierda, y los detalles del seleccionado a la derecha. Cada uno se desplaza por su cuenta, así que una lista larga de plugins y un formulario largo de ajustes no se arrastran mutuamente.</p><p>Si no hay ningún plugin instalado, la página muestra en su lugar un mensaje de estado vacío.</p><h2 id="lista-de-plugins" tabindex="-1">Lista de plugins <a class="header-anchor" href="#lista-de-plugins" aria-label="Permalink to &quot;Lista de plugins&quot;">​</a></h2><p>Una fila por plugin instalado, con su nombre y debajo su versión. Al seleccionar una fila, ese plugin se abre en el panel de la derecha.</p><p>La lista encabeza con lo que hay que hacer: primero los plugins con ajustes propios, después los que tienen componentes que puedes desactivar, y luego el resto, por orden alfabético dentro de cada grupo.</p><h2 id="plugin-seleccionado" tabindex="-1">Plugin seleccionado <a class="header-anchor" href="#plugin-seleccionado" aria-label="Permalink to &quot;Plugin seleccionado&quot;">​</a></h2><p>El panel empieza con el icono, el nombre y la <strong>descripción general de la función</strong> del plugin.</p><p>Debajo, un plugin que expone su propia configuración (ajustes personalizados más allá de un simple habilitar/deshabilitar) obtiene dos pestañas, <strong>Detalles</strong> y <strong>Configurar</strong>. Un plugin sin nada que configurar no muestra ninguna pestaña: sus detalles ocupan el panel entero.</p><h3 id="detalles" tabindex="-1">Detalles <a class="header-anchor" href="#detalles" aria-label="Permalink to &quot;Detalles&quot;">​</a></h3><p>Los componentes que registra este plugin, agrupados por tipo (proveedores de búsqueda, proveedores de menú dinámico, etc.). Cada componente activable tiene su propia <strong>casilla de habilitar/deshabilitar</strong>; un componente marcado como obligatorio muestra en su lugar un icono de candado y no se puede desactivar. Al pasar el cursor sobre el <strong>(!)</strong> junto a un componente se revela su descripción detallada de función.</p><p>Cuando un grupo (o el plugin en su conjunto) tiene más de un componente activable, aparece un enlace <strong>Seleccionar todo / Deseleccionar todo</strong> junto a su encabezado, que permite marcar/desmarcar todas las casillas de ese ámbito a la vez en lugar de una por una.</p><h3 id="configurar" tabindex="-1">Configurar <a class="header-anchor" href="#configurar" aria-label="Permalink to &quot;Configurar&quot;">​</a></h3><p>Los ajustes propios del plugin, editados aquí mismo en lugar de en un diálogo aparte. Un plugin que reparte sus ajustes en dos o más grupos obtiene su propia fila de pestañas, una por grupo.</p><p>No se escribe nada hasta que pulsas <strong>Aceptar</strong>. Al salir de esta pestaña — volviendo a Detalles, o eligiendo otro plugin — los campos vuelven a sus valores guardados, de modo que unas ediciones que dejaste atrás no puedan confirmarse más tarde por descuido.</p><p>Para ver un ejemplo concreto de cómo es en la práctica la configuración de un plugin (por ejemplo, cambiar una palabra clave de activación), ver <a href="./../instant-answers.html">Respuestas instantáneas y atajos de palabra clave</a>.</p>',17)])])}const m=a(l,[["render",r]]);export{g as __pageData,m as default};
